from itertools import combinations
from typing import FrozenSet, Iterable, List, Optional, Tuple

Edge = FrozenSet[int]
Coloring = FrozenSet[Edge]

def is_red(c: Coloring, u: int, v: int) -> bool:
    return frozenset((u, v)) in c

def has_mono_clique(c: Coloring, V: Iterable[int], k: int,
                    red: bool) -> Optional[Tuple[int, ...]]:
    for cand in combinations(sorted(V), k):
        if all(is_red(c, u, v) == red for u, v in combinations(cand, 2)):
            return cand
    return None

def arrows(n: int, s: int, t: int) -> bool:
    V = list(range(n))
    E = [frozenset(e) for e in combinations(V, 2)]
    for mask in range(1 << len(E)):
        c = frozenset(E[i] for i in range(len(E)) if (mask >> i) & 1)
        if (has_mono_clique(c, V, s, True) is None and
                has_mono_clique(c, V, t, False) is None):
            return False
    return True

def pentagon() -> Coloring:
    return frozenset(frozenset((i, (i + 1) % 5)) for i in range(5))

if __name__ == '__main__':
    print('6 -> (3,3):', arrows(6, 3, 3))            # True  (upper bound)
    c = pentagon()
    no_tri = (has_mono_clique(c, range(5), 3, True) is None and
              has_mono_clique(c, range(5), 3, False) is None)
    print('pentagon escapes K5:', no_tri)             # True  (lower bound)
    print('=> R(3,3) = 6:', arrows(6, 3, 3) and no_tri)

