from itertools import combinations
from math import comb
from typing import FrozenSet, List, Tuple

Edge = FrozenSet[int]
Coloring = FrozenSet[Edge]

def is_red(c: Coloring, u: int, v: int) -> bool:
    return frozenset((u, v)) in c

def es_construct_clique(c: Coloring, V: List[int], s: int,
                        t: int) -> Tuple[bool, Tuple[int, ...]]:
    if s == 1:
        return True, (V[0],)
    if t == 1:
        return False, (V[0],)
    v, rest = V[0], V[1:]
    red_nb = [u for u in rest if is_red(c, v, u)]
    blue_nb = [u for u in rest if not is_red(c, v, u)]
    m = comb((s - 1) + (t - 1) - 1, (s - 1) - 1)
    if len(red_nb) >= m:
        r, cl = es_construct_clique(c, red_nb, s - 1, t)
        return (True, (v,) + cl) if r else (False, cl)
    r, cl = es_construct_clique(c, blue_nb, s, t - 1)
    return (False, (v,) + cl) if not r else (True, cl)

if __name__ == '__main__':
    cyc = {frozenset((i, (i + 1) % 5)) for i in range(5)}
    c = frozenset(cyc | {frozenset((5, i)) for i in (0, 2)})
    red, clique = es_construct_clique(c, list(range(6)), 3, 3)
    ok = all(is_red(c, u, v) == red for u, v in combinations(clique, 2))
    print(('RED' if red else 'BLUE'), 'triangle', clique, 'verified', ok)

