function ES_CLIQUE(coloring, V, s, t):
    if s == 1: return (RED,  [V[0]])
    if t == 1: return (BLUE, [V[0]])
    v <- V[0];  rest <- V[1:]
    Rnb <- { u in rest : edge {v,u} is RED }
    Bnb <- { u in rest : edge {v,u} is BLUE }
    m   <- C((s-1)+(t-1)-1, (s-1)-1)      # threshold for (s-1, t)
    if |Rnb| >= m:
        (c, clique) <- ES_CLIQUE(coloring, Rnb, s-1, t)
        if c == RED:  return (RED, [v] ++ clique)
        else:         return (BLUE, clique)
    else:
        (c, clique) <- ES_CLIQUE(coloring, Bnb, s, t-1)
        if c == BLUE: return (BLUE, [v] ++ clique)
        else:         return (RED, clique)

