        if all pairs in S have the required colour: return True
    return False

function ES_TABLE(K):
    C <- (K+1) x (K+1) array of zeros
    for i in 0..K: C[i][0] <- 1; C[0][i] <- 1
    for s in 1..K:
        for t in 1..K:
            C[s][t] <- C[s-1][t] + C[s][t-1]   # Pascal's rule on C(s+t,s)
    return C          # C[s][t] = C(s+t,s) >= R(s+1,t+1)

